// Webflow on a site API token: every operation of Webflow's Data API v2 a site token can call (sites, pages, CMS
// collections and items, forms, assets, comments, components, shop products and orders, analytics, Enterprise site
// settings). actions.json is generated by `bun scripts/openapi-actions.ts webflow`; upload_asset is written here.
// Forms, publishes, pages, orders, inventory, CMS items and comments start automations by webhook (triggers.ts);
// new products and assets are polled (polls/webflow.ts). COVERAGE.md says what's where.
import { createHash } from "node:crypto";
import { z } from "zod";
import { AppFile, AppsError } from "../../types";
import type { OwnApp, OwnAction } from "../index";
import { type Api, call, type Send, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

export const api: Api = {
  name: "Webflow",
  base: "https://api.webflow.com/v2",
  tokenHelp: "Webflow → the site's Site settings → Apps & integrations → API access → Generate API token",
};

const FILE = new URL("./actions.json", import.meta.url);
const actions = await specActions(FILE, api);

// Webflow reads some query params in brackets (createdOn[gte]=..., filter[country][in][0]=US), which the generic
// runner would send as JSON: spread them out first
export const brackets = (key: string, v: unknown): [string, unknown][] =>
  v !== null && typeof v === "object" ? Object.entries(v).flatMap(([k, x]) => brackets(`${key}[${k}]`, x)) : [[key, v]];
type Generated = { name: string; send: Send; deep?: string[] };
for (const a of ((await Bun.file(FILE).json()) as { actions: Generated[] }).actions) {
  if (!a.deep) continue;
  const deep = a.deep;
  actions[a.name]!.run = (i: Record<string, unknown>, key: string) => {
    const flat = Object.fromEntries(Object.entries(i).flatMap(([k, v]) => (deep.includes(k) ? brackets(k, v) : [[k, v]])));
    const query = [...a.send.query.filter((q) => !deep.includes(q)), ...Object.keys(flat).filter((k) => deep.some((d) => k.startsWith(`${d}[`)))];
    return call(api, key, { ...a.send, query }, flat);
  };
}

const CREATE_ASSET: Send = { method: "POST", path: "/sites/{site_id}/assets", query: [], headers: [], body: { kind: "fields", fields: [["fileName", "fileName"], ["fileHash", "fileHash"], ["parentFolder", "parentFolder"]] } };
// Webflow's upload is two steps (tell Webflow, then send the file to its storage); this does both
const upload_asset: OwnAction = {
  description: "Upload a file (an image, a PDF, a video...) to the Webflow site's Assets panel, so pages and CMS items can use it. Answers its id and hostedUrl.",
  input: z.object({
    site_id: z.string().describe("The Webflow site's id (list_webflow_sites gives it)"),
    file: z.any().describe('The file from the computer: {"file": "/work/photo.jpg"}. Its name is the asset\'s name (under 100 characters)'),
    parentFolder: z.string().optional().describe("Put it in this asset folder (its id; list_asset_folders lists them)"),
  }),
  async run(i, key) {
    if (!(i.file instanceof AppFile)) throw new AppsError('file: give the file as {"file": "/work/photo.jpg"}');
    const file = i.file as AppFile;
    const fileHash = createHash("md5").update(file.bytes).digest("hex");
    const made = (await call(api, key, CREATE_ASSET, { site_id: i.site_id, fileName: file.name, fileHash, parentFolder: i.parentFolder })) as { uploadUrl: string; uploadDetails: Record<string, string>; [k: string]: unknown };
    const form = new FormData();
    for (const [k, v] of Object.entries(made.uploadDetails ?? {})) form.append(k, String(v));
    form.append("file", new Blob([file.bytes as Uint8Array<ArrayBuffer>], { type: file.mimetype }), file.name);
    const res = await fetch(made.uploadUrl, { method: "POST", body: form });
    if (!res.ok) throw new AppsError(`Webflow: the file didn't upload (${res.status})`);
    const { uploadUrl: _, uploadDetails: __, ...asset } = made;
    return asset;
  },
};

export const webflow: OwnApp = {
  app: "webflow",
  name: "Webflow",
  logo: "/logos/webflow.svg",
  keyField: {
    label: "Site API token",
    help: "In Webflow, open the site's Site settings → Apps & integrations → API access, click Generate API token, name it Emplio and give every scope Read and write (only a site's admin can do this). Copy the token, which is shown once. A token covers one site; to connect another site, make a token there too.",
    placeholder: "a1b2c3d4e5f6...",
  },
  async check(key) {
    const { sites } = (await call(api, key, { method: "GET", path: "/sites", query: [], headers: [] }, {})) as { sites?: { displayName?: string; shortName?: string }[] };
    if (!sites?.length) throw new AppsError("Webflow accepted the token but it doesn't reach any site; give it the Sites read scope", true);
    return sites.map((s) => s.displayName || s.shortName).join(", ");
  },
  push: {
    events,
    triggers,
    start: (key, connection, event, config) => watch(api, key, connection, event, config),
    stop: (key, id) => unwatch(api, key, id),
    receive,
    wanted,
  },
  actions: { ...actions, upload_asset },
};
